pecas.css:
.bio-hero-banner {
  text-align: center;
  padding: 2rem 1.5rem 1.5rem;
  background: linear-gradient(135deg, #6366f1 0%, #ec4899 100%);
  border-radius: 20px;
  margin: 1.5rem auto 0;
  max-width: 680px;
  color: #ffffff;
}
.bio-hero-banner h1 {
  font-size: clamp(1.3rem, 3vw, 1.75rem);
  font-weight: 800;
  margin-bottom: 0.5rem;
}
.bio-hero-banner p {
  font-size: 0.95rem;
  opacity: 0.92;
  margin: 0;
}

cssVariantes:
.bio-hero-banner {
  text-align: center;
  padding: 2rem 1.5rem 1.5rem;
  background: linear-gradient(135deg, #6366f1 0%, #ec4899 100%);
  border-radius: 20px;
  margin: 1.5rem auto 0;
  max-width: 680px;
  color: #ffffff;
}
.bio-hero-banner h1 {
  font-size: clamp(1.3rem, 3vw, 1.75rem);
  font-weight: 800;
  margin-bottom: 0.5rem;
}
.bio-hero-banner p {
  font-size: 0.95rem;
  opacity: 0.92;
  margin: 0;
}

.bio-hero-banner--glass {
  text-align: left;
  padding: 1.75rem 1.5rem;
  background: rgba(99, 102, 241, 0.12);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(99, 102, 241, 0.35);
  border-radius: 18px;
  margin: 1.5rem auto 0;
  max-width: 680px;
  color: #1e1b4b;
}
.bio-hero-banner-wave {
  display: inline-block;
  font-size: 1.4rem;
  margin-bottom: 0.35rem;
}
.bio-hero-banner--glass h1 {
  font-size: clamp(1.3rem, 3vw, 1.75rem);
  font-weight: 800;
  margin: 0 0 0.5rem;
}
.bio-hero-banner--glass p {
  font-size: 0.95rem;
  opacity: 0.85;
  margin: 0;
}

.bio-hero-banner--flat {
  text-align: left;
  padding: 1.5rem 1.5rem 1.5rem 1.25rem;
  background: #f8fafc;
  border-left: 4px solid #6366f1;
  border-radius: 6px;
  margin: 1.5rem auto 0;
  max-width: 680px;
  color: #1e293b;
}
.bio-hero-banner--flat h1 {
  font-size: clamp(1.25rem, 2.8vw, 1.6rem);
  font-weight: 800;
  margin: 0 0 0.4rem;
}
.bio-hero-banner--flat p {
  font-size: 0.9rem;
  color: #475569;
  margin: 0;
}

.bio-hero-banner--spotlight {
  text-align: center;
  padding: 2.25rem 1.5rem;
  background: radial-gradient(circle at 50% 0%, rgba(236, 72, 153, 0.35), rgba(17, 24, 39, 0) 60%), #111827;
  border-radius: 20px;
  margin: 1.5rem auto 0;
  max-width: 680px;
  color: #ffffff;
}
.bio-hero-banner--spotlight h1 {
  font-size: clamp(1.3rem, 3vw, 1.8rem);
  font-weight: 800;
  margin: 0 0 0.5rem;
  text-shadow: 0 0 18px rgba(236, 72, 153, 0.55);
}
.bio-hero-banner--spotlight p {
  font-size: 0.95rem;
  color: #cbd5e1;
  margin: 0;
}

.bio-hero-banner--duotone {
  text-align: center;
  padding: 2rem 1.5rem 1.5rem;
  background: linear-gradient(135deg, #6366f1 0%, #6366f1 50%, #ec4899 50%, #ec4899 100%);
  border-radius: 20px;
  margin: 1.5rem auto 0;
  max-width: 680px;
  color: #ffffff;
}
.bio-hero-banner-badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  margin-bottom: 0.6rem;
  border-radius: 50rem;
  background: rgba(255, 255, 255, 0.2);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.4px;
}
.bio-hero-banner--duotone h1 {
  font-size: clamp(1.3rem, 3vw, 1.75rem);
  font-weight: 800;
  margin: 0 0 0.5rem;
}
.bio-hero-banner--duotone p {
  font-size: 0.95rem;
  opacity: 0.92;
  margin: 0;
}
